#include <vector>
#include <string>
#include <sstream>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<string> sortFeatures(vector<string>& features, vector<string>& responses) {
        unordered_map<string, int> freq;
        unordered_map<string, int> order;
        for (int i = 0; i < features.size(); ++i) {
            freq[features[i]] = 0;
            order[features[i]] = i;
        }

        for (const string& r : responses) {
            stringstream ss(r);
            string word;
            unordered_set<string> seen;
            while (ss >> word) {
                seen.insert(word);
            }
            for (const string& w : seen) {
                if (freq.count(w)) {
                    freq[w]++;
                }
            }
        }

        vector<string> res = features;
        stable_sort(res.begin(), res.end(), [&](const string& a, const string& b) {
            if (freq[a] != freq[b]) return freq[a] > freq[b];
            return order[a] < order[b];
        });
        return res;
    }
};

import java.util.*;

class Solution {
    public String[] sortFeatures(String[] features, String[] responses) {
        Map<String, Integer> freq = new HashMap<>();
        Map<String, Integer> order = new HashMap<>();
        for (int i = 0; i < features.length; ++i) {
            freq.put(features[i], 0);
            order.put(features[i], i);
        }

        for (String r : responses) {
            Set<String> seen = new HashSet<>(Arrays.asList(r.split(" ")));
            for (String w : seen) {
                if (freq.containsKey(w)) {
                    freq.put(w, freq.get(w) + 1);
                }
            }
        }

        String[] res = features.clone();
        Arrays.sort(res, (a, b) -> {
            int fa = freq.get(a), fb = freq.get(b);
            if (fa != fb) return Integer.compare(fb, fa);
            return Integer.compare(order.get(a), order.get(b));
        });
        return res;
    }
}

/**
 * @param {string[]} features
 * @param {string[]} responses
 * @return {string[]}
 */
var sortFeatures = function(features, responses) {
    const freq = new Map();
    const order = new Map();
    for (let i = 0; i < features.length; ++i) {
        freq.set(features[i], 0);
        order.set(features[i], i);
    }

    for (const r of responses) {
        const words = new Set(r.split(' '));
        for (const w of words) {
            if (freq.has(w)) {
                freq.set(w, freq.get(w) + 1);
            }
        }
    }

    return [...features].sort((a, b) => {
        const fa = freq.get(a), fb = freq.get(b);
        if (fa !== fb) return fb - fa;
        return order.get(a) - order.get(b);
    });
};
